export PATH=/root/miniconda3/bin:$PATH && python3 << 'PYEOF'
import json
from collections import defaultdict, Counter

def safe_str(val):
    if isinstance(val, list): return val[0] if val else "NONE"
    return str(val) if val is not None else "NONE"

def load_jsonl(path):
    recs = []
    with open(path) as f:
        for line in f:
            line = line.strip()
            if line:
                try: recs.append(json.loads(line))
                except: pass
    return recs

with open("/root/schema_semantic_constrained_ie/ontology_constraints.json") as f:
    onto = json.load(f)
valid_et = set(onto["entity_types"])
valid_rt = set(onto["relation_types"])
valid_dr = {}
for rel, info in onto["relation_constraints"].items():
    valid_dr[rel] = set(tuple(p) for p in info["valid_pairs"])

results = {}

# 70B SciERC
for label, path in [
    ("70b_sci_con", "/root/autodl-tmp/schema_outputs/70b_scierc_constrained.jsonl"),
    ("70b_sci_uncon", "/root/autodl-tmp/schema_outputs/70b_scierc_unconstrained.jsonl"),
]:
    recs = load_jsonl(path)
    te, tr, et_v, rv_v, dr_v, cf_ents, pf = 0, 0, 0, 0, 0, 0, 0
    dr_detail, rv_detail = Counter(), Counter()
    cf_detail = []

    for rec in recs:
        p = rec.get("parsed_output")
        if not p: pf += 1; continue
        ents, rels = p.get("entities", []), p.get("relations", [])
        te += len(ents); tr += len(rels)
        for e in ents:
            if safe_str(e.get("type")) not in valid_et: et_v += 1
        for r in rels:
            rt, ht, tt = safe_str(r.get("type")), safe_str(r.get("head_type")), safe_str(r.get("tail_type"))
            if rt not in valid_rt: rv_v += 1; rv_detail[rt] += 1
            elif rt in valid_dr and (ht, tt) not in valid_dr[rt]: dr_v += 1; dr_detail[f"{rt}: {ht}->{tt}"] += 1
        etypes = defaultdict(set)
        for e in ents: etypes[safe_str(e.get("text")).lower()].add(safe_str(e.get("type")))
        for r in rels:
            etypes[safe_str(r.get("head")).lower()].add(safe_str(r.get("head_type")))
            etypes[safe_str(r.get("tail")).lower()].add(safe_str(r.get("tail_type")))
        for txt, ts in etypes.items():
            if len(ts) > 1:
                cf_ents += 1
                if len(cf_detail) < 15: cf_detail.append({"doc_id": rec["doc_id"], "entity": txt, "types": sorted(ts)})

    print(f"{label}: docs={len(recs)}, E={te}, R={tr}, PF={pf}")
    print(f"  ET={et_v/te*100 if te else 0:.1f}%, RV={rv_v/tr*100 if tr else 0:.1f}%, DR={dr_v/tr*100 if tr else 0:.1f}%, CF_ents={cf_ents}")
    if dr_detail: print(f"  Top DR: {dr_detail.most_common(5)}")
    if rv_detail: print(f"  Top RV: {rv_detail.most_common(5)}")
    results[label] = {"docs": len(recs), "pf": pf, "te": te, "tr": tr, "et": et_v, "rv": rv_v, "dr": dr_v, "cf_ents": cf_ents,
                      "dr_detail": dict(dr_detail.most_common(20)), "rv_detail": dict(rv_detail.most_common(20)), "cf_detail": cf_detail}

# Case studies
con = load_jsonl("/root/autodl-tmp/schema_outputs/70b_scierc_constrained.jsonl")
uncon = load_jsonl("/root/autodl-tmp/schema_outputs/70b_scierc_unconstrained.jsonl")
umap = {r["doc_id"]: r for r in uncon}
cmap = {r["doc_id"]: r for r in con}
fixed = []
for did in umap:
    if did not in cmap: continue
    up, cp = umap[did].get("parsed_output", {}), cmap[did].get("parsed_output", {})
    if not up or not cp: continue
    u_dr, u_viol = 0, []
    for r in up.get("relations", []):
        rt, ht, tt = safe_str(r.get("type")), safe_str(r.get("head_type")), safe_str(r.get("tail_type"))
        if rt in valid_dr and (ht, tt) not in valid_dr[rt]: u_dr += 1; u_viol.append(r)
    c_dr = sum(1 for r in cp.get("relations", []) if safe_str(r.get("type")) in valid_dr and (safe_str(r.get("head_type")), safe_str(r.get("tail_type"))) not in valid_dr[safe_str(r.get("type"))])
    if u_dr > 0 and c_dr == 0:
        fixed.append({"doc_id": did, "input": umap[did].get("input_text",""), "u_dr": u_dr, "u_viol": u_viol,
                      "u_ents": up.get("entities",[]), "u_rels": up.get("relations",[]),
                      "c_ents": cp.get("entities",[]), "c_rels": cp.get("relations",[]),
                      "gold_ents": umap[did].get("gold_entities",[]), "gold_rels": umap[did].get("gold_relations",[])})
fixed.sort(key=lambda x: x["u_dr"], reverse=True)
results["cases_fixed"] = fixed[:10]
print(f"\n70B SciERC: {len(fixed)} DR-fixed cases")

# Mistral DocRED
with open("/root/schema_semantic_constrained_ie/data/docred/ontology_constraints_docred.json") as f:
    d = json.load(f)
det, drc = set(d["entity_types"]), set(d["relation_types"].keys())
dn2c = {v:k for k,v in d["relation_types"].items()}
ddr = {rc: set(tuple(p) for p in info["valid_pairs"]) for rc, info in d["relation_constraints"].items()}

for label, path in [
    ("mis_doc_con", "/root/schema_semantic_constrained_ie/outputs/w6_mistral_docred_constrained.jsonl"),
    ("mis_doc_uncon", "/root/schema_semantic_constrained_ie/outputs/w6_mistral_docred_unconstrained.jsonl"),
]:
    recs = load_jsonl(path)
    te, tr, et_v, rv_v, dr_v, cf_ents, pf = 0, 0, 0, 0, 0, 0, 0
    drd, rvd = Counter(), Counter()
    for rec in recs:
        p = rec.get("parsed_output")
        if not p: pf+=1; continue
        ents, rels = p.get("entities",[]), p.get("relations",[])
        te += len(ents); tr += len(rels)
        for e in ents:
            if safe_str(e.get("type")) not in det: et_v += 1
        for r in rels:
            rt, ht, tt = safe_str(r.get("type")), safe_str(r.get("head_type")), safe_str(r.get("tail_type"))
            rc = rt if rt in drc else dn2c.get(rt)
            if rc is None: rv_v += 1; rvd[rt] += 1
            elif rc in ddr and (ht, tt) not in ddr[rc]: dr_v += 1; drd[f"{rc}: {ht}->{tt}"] += 1
        etypes = defaultdict(set)
        for e in ents: etypes[safe_str(e.get("text")).lower()].add(safe_str(e.get("type")))
        for r in rels:
            etypes[safe_str(r.get("head")).lower()].add(safe_str(r.get("head_type")))
            etypes[safe_str(r.get("tail")).lower()].add(safe_str(r.get("tail_type")))
        for _,ts in etypes.items():
            if len(ts)>1: cf_ents+=1
    print(f"\n{label}: docs={len(recs)}, E={te}, R={tr}, PF={pf}")
    print(f"  ET={et_v/te*100 if te else 0:.1f}%, RV={rv_v/tr*100 if tr else 0:.1f}%, DR={dr_v/tr*100 if tr else 0:.1f}%, CF_ents={cf_ents}")
    if drd: print(f"  Top DR: {drd.most_common(5)}")
    if rvd: print(f"  Top RV: {rvd.most_common(5)}")
    results[label] = {"docs":len(recs),"pf":pf,"te":te,"tr":tr,"et":et_v,"rv":rv_v,"dr":dr_v,"cf_ents":cf_ents,
                      "dr_detail":dict(drd.most_common(20)),"rv_detail":dict(rvd.most_common(20))}

print(json.dumps(results, indent=2, default=str)[:200])
with open("/root/schema_semantic_constrained_ie/p3_70b_results.json","w") as f:
    json.dump(results, f, indent=2, default=str)
print("\nDone")
PYEOF

